package com.aicommerce.platform.delivery.application.port;
import java.util.*; import com.aicommerce.platform.delivery.domain.*;
public record NormalizedPlatformEvidence(int schemaVersion,ProviderKey providerKey,PlatformAttemptKind attemptKind,PlatformEvidenceResultKind resultKind,Optional<String> externalIdFingerprint,Optional<PlatformObservedState> observedState,Optional<Integer> retryAfterSeconds){public NormalizedPlatformEvidence{PlatformContractSupport.req(providerKey);PlatformContractSupport.req(attemptKind);PlatformContractSupport.req(resultKind);externalIdFingerprint=PlatformContractSupport.opt(externalIdFingerprint);observedState=PlatformContractSupport.opt(observedState);retryAfterSeconds=PlatformContractSupport.opt(retryAfterSeconds);externalIdFingerprint.ifPresent(PlatformContractSupport::hash);if(schemaVersion!=1||providerKey!=ProviderKey.FAKE||retryAfterSeconds.filter(v->v<1||v>3600).isPresent())throw PlatformContractSupport.invalid();}}
